  /**
   * ステップフローの初期化
   *
   */
  initFlowNavi: function initFlowNavi() {
    var $container = $('.js_flow_nav');
    var $all_items = $container.find('[data-flow-id]');
    var items = {};
    var links = {};
    $all_items.each(function () {
      var $this = $(this);
      var id = $this.data('flow-id');
      var $link = $this.find('a');
      items[id] = $this;
      links[id] = $link;
    });
    ENGINE.Simulator.flow_nav = {
      'container': $container,
      'all-items': $all_items,
      'items': items,
      'links': links
    };
  },
