  /**
   * 画面遷移リストがら画面IDを取得
   *
   */
  popPanalHistory: function popPanalHistory() {
    if (ENGINE.Simulator.panel_history_list.length > 0) {
      ENGINE.Simulator.panel_history_list.pop();
    }

    var length = ENGINE.Simulator.panel_history_list.length;
    var panel_id = 'top';

    if (length > 0) {
      panel_id = ENGINE.Simulator.panel_history_list[length - 1];
    }

    return panel_id;
  },

