  /**
   * Colour変更時の再計算処理
   *
   */
  recalculationPrice: function recalculationPrice(src_faucet_id, src_faucet_colour) {
    var faucet_id = src_faucet_id ? src_faucet_id : ENGINE.Simulator.condition['faucet-product'];
    var faucet_colour = src_faucet_colour ? src_faucet_colour : ENGINE.Simulator.condition['faucet-colour']; // 書き換え対象フィールドの取得

    var $faucet_price = $('.js-faucet-price');
    var $total_price = $('.js-total-price'); // 書き換え対象のフィールドがある場合のみ

    if ($faucet_price.length > 0) {
      var total = 0; // Faucetの金額取得

      var faucet = ENGINE.Simulator.vars.faucet_master[faucet_id];
      var faucet_price = ENGINE.Simulator.getColourPrice(faucet, faucet_colour);
      total += Number(faucet_price); // Faucet金額の再表示

      $faucet_price.html(ENGINE.SimulatorCommon.priceFormat(faucet_price, ENGINE.Simulator.settings)); // Laavtoryの金額取得

      var lavatory_id = ENGINE.Simulator.condition['lavatory-product'];

      if (lavatory_id) {
        var lavatory = ENGINE.Simulator.vars.lavatory_master[lavatory_id];
        var lavatory_price = lavatory['PRICE'];
        total += Number(lavatory_price);
      } // Faucet Optionの金額取得


      var field_id, product_id, product, product_price;
      var calc_option_list = ['soapdispenser-product', 'soaptank-product', 'controller-unit-product', 'controller-option-product'];

      for (var i = 0, max = calc_option_list.length; i < max; i++) {
        field_id = calc_option_list[i];
        product_id = ENGINE.Simulator.condition[field_id];

        if (product_id) {
          product = ENGINE.Simulator.vars.faucet_master[product_id];

          if (product) {
            product_price = product['PRICE'];
            total += Number(product_price);
          }
        }
      } // 合計金額の再表示


      if ($total_price.length > 0) {
        $total_price.html(ENGINE.SimulatorCommon.priceFormat(total, ENGINE.Simulator.settings));
      }
    }
  },

