  /**
   * 結果画面用
   *
   */
  generateCodeResult: function generateCodeResult(stage_id, faucet_id, faucet_colour, lavatory_id, show_soapdispenser) {
    var code = ''; // 結果画像

    code += '<div class="m_result is-faucet-lavatory">';
    code += ENGINE.Simulator.generateCodeResultImage('m_result', faucet_id, faucet_colour, lavatory_id, show_soapdispenser);
    code += '</div>';
    code += '<div class="m_result__footer">';
    var result_annotation = ENGINE.SimulatorCommon.nl2br(ENGINE.Simulator.messages['result_annotation']);

    if (ENGINE.Simulator.messages['result_annotation_ex_faucet']) {
      result_annotation += '<br>' + ENGINE.SimulatorCommon.nl2br(ENGINE.Simulator.messages['result_annotation_ex_faucet']);
    }

    code += '<p class="m_result__note is_static m_inner_padding_sp">' + result_annotation + '</p>';
    code += '<ul class="m_result__btn is_static m_inner_padding_sp">';
    code += '<li class="m_btn__black"><a href="#" data-action-link="add-favorite"><i class="m_icon__star--white m_mgr5"></i>' + ENGINE.Simulator.messages['add_favarite_link'] + '</a></li>'; // PDFダウンロード

    if (ENGINE.Simulator.settings['pdf_flg']) {
      code += '<li class="m_btn__black"><a href="#" data-action-link="download-pdf"><i class="m_icon__download--white m_mgr5"></i>' + ENGINE.Simulator.messages['download_link'] + '</a></li>';
    } // Share


    if (ENGINE.Simulator.settings['sns_flg']) {
      code += '<li class="m_btn__black"><a href="#" data-action-link="open-share"><i class="m_icon__share--white m_mgr5"></i>' + ENGINE.Simulator.messages['share_link'] + '</a></li>';
    }

    code += '</ul>';
    code += '</div>';
    return code;
  },

